<template>
  <AppMultiComboboxQuery
    v-if="isMultiple"
    :items="selectItems"
    :value="value"
    :property-name="propertyName"
    :null-is-all="nullIsAll"
    :placeholder="placeholder"
    :input-placeholder="inputPlaceholder"
    :loading="isLoading"
    :error="error"
    :items-plural-name="itemsPluralName"
    :empty-text="emptyText"
    :icon="icon || FilterIcon"
    :is-first-page-only="isFirstPageOnly"
  />
  <AppComboboxQuery
    v-else
    :items="selectItems"
    :value="value ? value[0] : null"
    :property-name="propertyName"
    :null-is-all="nullIsAll"
    :placeholder="placeholder"
    :input-placeholder="inputPlaceholder"
    :loading="isLoading"
    :error="error"
    :items-plural-name="itemsPluralName"
    :empty-text="emptyText"
    :icon="icon || FilterIcon"
    :is-first-page-only="isFirstPageOnly"
  />
</template>
<script setup lang="ts">
import { getSelectorProjectRegions, type GetSelectorProjectRegionsResponse } from '~/client';
import { FilterIcon } from 'lucide-vue-next';

const props = withDefaults(
  defineProps<{
    value: string[] | null;
    propertyName: string;
    projectId: string;

    placeholder: string;
    inputPlaceholder: string;
    emptyText: string;
    nullIsAll: boolean;
    itemsPluralName: string;
    icon?: any;
    isMultiple?: boolean;
    isFirstPageOnly?: boolean;
  }>(),
  {
    icon: undefined,
    isMultiple: true,
    isFirstPageOnly: true,
  }
);

const { data, isLoading, error } = useQuery({
  key: () => ['selector-project-regions-list', props.projectId, props.isMultiple],
  query: (): Promise<GetSelectorProjectRegionsResponse> =>
    getSelectorProjectRegions({
      composable: '$fetch',
      path: { project_id: props.projectId },
    }),
});

const selectItems = computed(() => {
  return (
    data.value?.items.map((item) => ({
      name: item,
      value: item,
    })) || []
  );
});
</script>
